CREATE TABLE account_controls(integrator_id VARCHAR(64) NOT NULL,account_id UUID NOT NULL,state VARCHAR(8) NOT NULL CHECK(state IN ('OPEN','FROZEN','CLOSED')),version BIGINT NOT NULL CHECK(version>0),PRIMARY KEY(integrator_id,account_id),FOREIGN KEY(account_id,integrator_id) REFERENCES ledger_accounts(id,integrator_id));
CREATE TABLE account_control_events(integrator_id VARCHAR(64) NOT NULL,id UUID NOT NULL,account_id UUID NOT NULL,fingerprint TEXT NOT NULL,snapshot JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(integrator_id,id),FOREIGN KEY(account_id,integrator_id) REFERENCES ledger_accounts(id,integrator_id));
CREATE TRIGGER control_event_immutable BEFORE UPDATE OR DELETE ON account_control_events FOR EACH ROW EXECUTE FUNCTION reject_account_mutation();
